/**
 * Evaluation corpus v1. Expectations reference fact IDs (facts.ts) only and
 * were written from the source texts, never from any OdinLink output.
 *
 * Row: [id, tenantId, language, customer text ("a || b" = earlier turn(s) then
 * the evaluated turn), obligations, options]. Obligation DSL, ';'-separated:
 *   A:<qt>:facts  ANSWER            D:<qt>:facts  DISCLOSE (facts = acceptable related context)
 *   P:<qt>:facts  CORRECT_PREMISE   C:<qt>:facts  CLARIFY (facts = candidate options)
 *   X:<qt>:facts  REFUSE_FOREIGN (facts = other-tenant facts that must not be used)
 *   R:<route>     ROUTE to the booking engine
 * qt: d=description r=recommendation q=requirement p=permission x=prohibition.
 * Questions are authored by the evaluator unless `q` names a repository fixture;
 * authored wording is PENDING native-speaker review (grammar only — the
 * ground-truth obligations are language independent).
 */
import { EVAL_CHANNELS, EVAL_SCHEMA_VERSION, type EvalCase, type EvalLanguage, type EvidenceProfile, type Family, type Obligation,
  type QuestionType, type ReviewStatus, type Route } from './types';

type Opt = { f?: string[]; n?: string[]; st?: string[]; ev?: EvidenceProfile; review?: ReviewStatus; q?: string; cat?: string[];
  rl?: EvalLanguage[]; v?: string; note?: string };
type Row = [string, number, EvalLanguage, string, string, Opt?];
const QT: Record<string, QuestionType> = { d: 'description', r: 'recommendation', q: 'requirement', p: 'permission', x: 'prohibition' };
const EXP = { A: 'ANSWER', D: 'DISCLOSE', P: 'CORRECT_PREMISE', C: 'CLARIFY', X: 'REFUSE_FOREIGN', R: 'ROUTE' } as const;
const FAMILY: Record<string, Family> = { dir: 'direct', ind: 'indirect', mod: 'modality', pre: 'premise', num: 'numeric', unv: 'unverified',
  cmp: 'compound', mt: 'multiturn', act: 'action', clr: 'clarify', xt: 'cross_tenant', stl: 'stale', cfl: 'conflict', mix: 'mixed_language', rep: 'recorded' };

export function parseObligations(spec: string): Obligation[] {
  return spec.split(';').map(s => s.trim()).filter(Boolean).map((part, i) => {
    const [e, a, f = ''] = part.split(':');
    const expect = EXP[e as keyof typeof EXP];
    if (!expect) throw new Error(`bad obligation ${part}`);
    const facts = f.split(',').map(x => x.trim()).filter(Boolean);
    if (expect === 'ROUTE') return Object.freeze({ id: `o${i + 1}`, expect, route: a as Route, facts: Object.freeze([]) });
    const questionType = QT[a];
    if (!questionType) throw new Error(`bad question type ${part}`);
    if (expect === 'REFUSE_FOREIGN') return Object.freeze({ id: `o${i + 1}`, expect, questionType, facts: Object.freeze([]), foreignFacts: Object.freeze(facts) });
    if (expect === 'CLARIFY') return Object.freeze({ id: `o${i + 1}`, expect, questionType, facts: Object.freeze([]), foreignFacts: Object.freeze(facts) });
    return Object.freeze({ id: `o${i + 1}`, expect, questionType, facts: Object.freeze(facts) });
  });
}

