const RECORDED_TENANT_ALIAS: Record<number, number> = { 77: 3 };
export const tenantOf = (id: number) => RECORDED_TENANT_ALIAS[id] ?? id;

function build(rows: readonly Row[]): EvalCase[] {
  return rows.map(([id, tenantId, language, text, spec, o = {}], i) => {
    const prefix = id.startsWith('var-') ? o.v!.split('-')[0] : id.split('-')[0];
    const family = FAMILY[prefix];
    if (!family) throw new Error(`unknown family for ${id}`);
    const obligations = parseObligations(spec);
    const categories = [...new Set([family, ...(o.cat ?? []), ...obligations.map(x => x.expect.toLowerCase()),
      ...obligations.flatMap(x => x.questionType ? [x.questionType] : []), ...(text.includes(' || ') ? ['multi-turn'] : ['single-turn'])])];
    return Object.freeze({ schema: EVAL_SCHEMA_VERSION, id, semanticKey: o.v ?? id, family, tenantId, language, replyLanguages: Object.freeze(o.rl ?? [language]),
      channel: EVAL_CHANNELS[i % EVAL_CHANNELS.length], turns: Object.freeze(text.split(' || ')), obligations: Object.freeze(obligations),
      forbiddenClaims: Object.freeze(o.f ?? []), ...(o.n ? { forbiddenNumbers: Object.freeze(o.n) } : {}), ...(o.st ? { forbiddenStaleText: Object.freeze(o.st) } : {}),
      evidenceProfile: o.ev ?? (family === 'cross_tenant' ? 'CROSS_TENANT' : 'CURRENT'), categories: Object.freeze(categories),
      provenance: Object.freeze({ question: o.q ?? 'authored-by-evaluator', review: o.review ?? 'AUTHORED_PENDING_NATIVE_REVIEW', ...(o.note ? { note: o.note } : {}) }) });
  });
}

export const CORPUS: readonly EvalCase[] = Object.freeze([...build(R), ...build(VARIANTS)]);
